vec2 cmul(vec2 mul1, vec2 mul2) {
vec2 mul = vec2(mul1.x*mul2.x - mul1.y*mul2.y, mul1.y*mul2.x + mul1.x*mul2.y);
return mul;
}
vec2 cdiv(vec2 div1, vec2 div2) {
vec2 div = vec2( (div1.x*div2.x + div1.y*div2.y)/(div2.x*div2.x + div2.y*div2.y),
(div1.y*div2.x + div1.x*div2.y)/(div2.x*div2.x + div2.y*div2.y) );
return div;
}
vec2 cpow(vec2 base, float ex) {
float moduz = sqrt(base.x*base.x + base.y*base.y);
float thetaz = atan(base.y, base.x);
vec2 pow = vec2(pow(moduz, ex)*cos(thetaz*ex), pow(moduz, ex)*sin(thetaz*ex));
return pow;
}
vec2 cexp(vec2 base, vec2 ex) {
float moduz = sqrt(base.x*base.x + base.y*base.y);
float thetaz = atan(base.y, base.x);
float mp = pow(moduz, ex.x)*exp(-ex.y*thetaz);
vec2 sol = mp*vec2(cos(ex.y*log(moduz) + ex.x*thetaz), sin(ex.y*log(moduz) + ex.x*thetaz));
return sol;
}
float getRad(vec2 uv1) {
return sqrt( pow(0.5-uv1.x, 2.0 ) + pow(0.5-uv1.y, 2.0 ) );
}
float getAng(vec2 uv1) {
vec2 uv2 = (uv1-0.5)*uAspect.xy;
return atan(uv2.y,uv2.x);
}
sampler sampler_rand02;
vec4  texsize_rand02;    // ...it's smart enough to get it from just this.
