vec2 uv2;
for (int i = 0; i < 3; i++)
{
z = cpow(z,zp)%c;
}
uv2 = z;
uv2 = 0.5 + (1.0 - abs( fract( uv2 * 0.5 ) * 2.0 - 1.0 )-0.5)*0.99; // Eo.S. mirror code with cutted borders
