((uv2.xyy*q27
)*uTexSize.xyy*texsize_noisevol_hq.zww
).xyz*
vec3( 1.0 , 1.0 , 0.0 )*0.05 +
uTime*vec3( 0.0 , 0.0 , 1.0 )*q29
