// Custom sampler stubs (mapped to noise texture)
#define sampler_rand00 sampler_noise_lq
sampler sampler_rand00;
vec2 factorA, factorB, product;
vec2 numerator, denominator, fraction;
vec2 complex_div(vec2 numerator, vec2 denominator){
return vec2( numerator.x*denominator.x + numerator.y*denominator.y,
numerator.y*denominator.x - numerator.x*denominator.y)/
(denominator.x*denominator.x + denominator.y*denominator.y);
}
vec2 uv_polar(vec2 domain, vec2 center){
vec2 c = domain - center;
float rad_hq = length(c);
float ang_hq = atan(c.x,c.y);
return vec2(ang_hq*M_INV_PI_2, rad_hq);
}
vec2 uv_polar_logarithmic(vec2 domain, vec2 center, int fins, float log_factor, vec2 coord){
vec2 polar = uv_polar(domain, center);
return vec2(polar.x*fins+coord.x, log_factor*log(polar.y) + coord.y);
}
vec2 uv_moebius_transformation(vec2 domain, vec2 zeroPoint, vec2 infinityPoint,float zoom){
return complex_div((domain - zeroPoint)*zoom, domain - infinityPoint)+0.5;
}
vec2 uv_bipolar(vec2 domain, vec2 northPole, vec2 southPole, int fins, float log_factor, vec2 coord){
vec2 help_uv = uv_moebius_transformation(domain, northPole, southPole, 1.0 );
return uv_polar_logarithmic(help_uv,0.5,fins,log_factor,coord);
}
vec2 uv_rotate( vec2 domain, vec2 center, float sinw, float cosw, float scale){
vec2 uv_r = (domain-center);
return center + vec2( cosw*uv_r.x - sinw*uv_r.y, sinw*uv_r.x + cosw*uv_r.y)*scale;
}
shader_body
{
vec2 rotate_uv = 0.5-uv_rotate(0.0 + (uv-0.5)*uAspect.xy, 0.0 , q3, q4, 2.0 );
vec2 bipolar_uv = uv_bipolar(rotate_uv,vec2( 0.0 ,0.5),vec2( 1.0 ,0.5), 2.0 , 0.3, vec2(q11,q12));
uv = 0.5 + (0.5 - abs( fract( bipolar_uv * 0.5 ) * 2.0 - 1.0 ));
vec2 uvo = uv;
uv = (uv-0.5);
factorA = uv+ vec2(q1,q2);
factorB = vec2( 8.0 , 0.0 );
product = vec2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
vec2 uv1 = product;
factorA = uv+ vec2(q3,q4);
factorB = vec2( 8.0 , 0.0 );
product = vec2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
vec2 uv2 = product;
factorA = uv+ vec2(q5,q6);
factorB = vec2( 8.0 , 0.0 );
product = vec2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
vec2 uv3 = product;
factorA = uv+ vec2(q7,q8);
factorB = vec2( 8.0 , 0.0 );
product = vec2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
vec2 uv4 = product;
factorA = uv1;
factorB = uv2;
product = vec2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
vec2 uv12 = product;
factorA = uv3;
factorB = uv4;
product = vec2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
vec2 uv34 = product;
factorA = uv12;
factorB = uv34;
product = vec2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
numerator = vec2( 1.0 , 0.0 );
denominator = product;
fraction = vec2( numerator.x*denominator.x + numerator.y*denominator.y,   // the fractions real part
numerator.y*denominator.x - numerator.x*denominator.y)/  // the fractions imaginary part
(denominator.x*denominator.x + denominator.y*denominator.y);
uv = fraction*( 16.0 );
uv = mix(0.5 + (uvo-0.5)*(2.0 + (audioLowSmooth-audioHighSmooth)*0.02),uv+0.5,0.5);
float l = length(uv-0.5);
uv = 0.5 + (1.0 - abs( fract( uv * 0.5 ) * 2.0 - 1.0 )-0.5); // Eo.S. mirror code with cutted borders
ret = texture( sampler_fc_main, uv );
vec4 noise9 = tex3D(sampler_noisevol_hq,
((uv12.xyy*q28
)*uTexSize.xyy*texsize_noisevol_hq.zww
).xyz*
vec3( 1.0 , 1.0 , 0.0 )*0.05 +
uTime*vec3( 0.0 , 0.0 , 1.0 )*q30
);
if(ret.x> q26*q3         && ret.x<= q23*q1        )ret.z -= (noise9).x*.5;
if(ret.y> q25*q1         && ret.y<= q22*q2        )ret.x -= (noise9).y*.5;
if(ret.z> q24*q2         && ret.z<= q21*q3        )ret.y -= (noise9).z*.5;
